mapper.select:
SELECT ar.id, ar.alert_no AS alertNo, ar.rule_id AS ruleId, ar.rule_name AS ruleName, ar.device_id AS deviceId, ar.device_code AS deviceCode, ar.device_name AS deviceName, ar.plot_id AS plotId, ar.plot_name AS plotName, ar.alert_level AS alertLevel, CASE ar.alert_level WHEN 1 THEN '紧急' WHEN 2 THEN '重要' WHEN 3 THEN '一般' WHEN 4 THEN '提醒' ELSE '未知' END AS alertLevelText, ar.property_code AS propertyCode, ar.property_name AS propertyName, ar.trigger_value AS triggerValue, ar.threshold_value AS thresholdValue, ar.alert_content AS alertContent, ar.alert_time AS alertTime, ar.handle_status AS handleStatus, CASE ar.handle_status WHEN 1 THEN '待处理' WHEN 2 THEN '处理中' WHEN 3 THEN '已处理' WHEN 4 THEN '已忽略' ELSE '未知' END AS handleStatusText, ar.handle_time AS handleTime, ar.handle_user AS handleUser, ar.handle_result AS handleResult, ar.create_time AS createTime FROM agri_iot_alert_record ar WHERE ar.del_flag = 0
AND ar.alert_no LIKE CONCAT('%', #{dto.alertNo}, '%')
AND ar.rule_name LIKE CONCAT('%', #{dto.ruleName}, '%')
AND ar.device_id = #{dto.deviceId}
AND ar.device_code LIKE CONCAT('%', #{dto.deviceCode}, '%')
AND ar.plot_id = #{dto.plotId}
AND ar.alert_level = #{dto.alertLevel}
AND ar.handle_status = #{dto.handleStatus}
AND ar.alert_time >= #{dto.startTime}
AND ar.alert_time <= #{dto.endTime}
ORDER BY ar.alert_time DESC LIMIT #{dto.pageNum}, #{dto.pageSize}

SELECT COUNT(*)
FROM agri_iot_alert_record ar
WHERE ar.del_flag = 0

    AND ar.alert_no LIKE CONCAT('%', #{dto.alertNo}, '%')


    AND ar.rule_name LIKE CONCAT('%', #{dto.ruleName}, '%')


    AND ar.device_id = #{dto.deviceId}


    AND ar.device_code LIKE CONCAT('%', #{dto.deviceCode}, '%')


    AND ar.plot_id = #{dto.plotId}


    AND ar.alert_level = #{dto.alertLevel}


    AND ar.handle_status = #{dto.handleStatus}


    AND ar.alert_time >= #{dto.startTime}


    AND ar.alert_time <= #{dto.endTime}
